import { createRouter } from '@tanstack/react-router'
// The route tree is generated by the TanStack Router plugin (do not edit)
import { routeTree } from '../routeTree.gen.ts'
import { ErrorPage } from '../shared/ui/error-page'
import { NotFoundPage } from '../shared/ui/not-found-page'

// No custom history is needed: TanStack Router creates the default browser
// history itself (and memory history when rendered without a DOM).
export const router = createRouter({
  routeTree,
  defaultNotFoundComponent: NotFoundPage,
  // App-level error boundary: catches render/loader errors inside routes.
  defaultErrorComponent: ErrorPage,
  // No `basepath`: '/' is the default.
})

// Register the router instance for end-to-end type safety
declare module '@tanstack/react-router' {
  interface Register {
    router: typeof router
  }
}
